import { type } from "arktype";

// Schema WITHOUT morph
const noMorph = type({
  name: "string",
  age: "number",
});

// Schema WITH morph (trim the string)
const withMorph = type({
  name: "string.trim",
  age: "number",
});

// Schema with pipe morph
const withPipeMorph = type({
  name: type("string").pipe((s) => s.toUpperCase()),
  age: "number",
});

const testData = { name: "  Alice  ", age: 30 };
const cleanData = { name: "Alice", age: 30 };

console.log("=== Arktype Morph Object Identity Test ===\n");

// Test without morph
const noMorphResult = noMorph(cleanData);
console.log("Without morph:");
console.log("  Result:", noMorphResult);
console.log("  Same object?", noMorphResult === cleanData);
console.log("");

// Test with built-in morph (trim)
const withMorphResult = withMorph(testData);
console.log("With string.trim morph:");
console.log("  Input:", testData);
console.log("  Result:", withMorphResult);
console.log("  Same object?", withMorphResult === testData);
if (typeof withMorphResult === "object" && withMorphResult !== null && "name" in withMorphResult) {
  console.log("  Result name:", JSON.stringify((withMorphResult as any).name));
}
console.log("");

// Test with pipe morph
const pipeMorphResult = withPipeMorph(testData);
console.log("With pipe morph (toUpperCase):");
console.log("  Input:", testData);
console.log("  Result:", pipeMorphResult);
console.log("  Same object?", pipeMorphResult === testData);
if (typeof pipeMorphResult === "object" && pipeMorphResult !== null && "name" in pipeMorphResult) {
  console.log("  Result name:", JSON.stringify((pipeMorphResult as any).name));
}
console.log("");

// Test nested object with morph
const nestedWithMorph = type({
  user: {
    name: "string.trim",
    email: "string.lower",
  },
});

const nestedData = { user: { name: "  Bob  ", email: "BOB@EXAMPLE.COM" } };
const nestedResult = nestedWithMorph(nestedData);
console.log("Nested object with morphs:");
console.log("  Input:", nestedData);
console.log("  Result:", nestedResult);
console.log("  Same outer object?", nestedResult === nestedData);
if (typeof nestedResult === "object" && nestedResult !== null && "user" in nestedResult) {
  console.log("  Same inner object?", (nestedResult as any).user === nestedData.user);
  console.log("  Result user:", (nestedResult as any).user);
}

import { makeData, makeSchema, randomString } from "./benchUtil.js";
import { metabench } from "./metabench.js";

const { zod3, zod4 } = makeSchema((z) => z.array(z.string()));
const DATA = makeData(1000, () => Array.from({ length: 3 }, () => randomString(10)));

// make sure they're working
console.log(zod3.parse(DATA[0]));
console.log(zod4.parse(DATA[0]));

const bench = metabench("z.array() parsing", {
  zod3() {
    for (const _ of DATA) zod3.parse(_);
  },
  zod4() {
    for (const _ of DATA) zod4.parse(_);
  },
});

await bench.run();

import { type } from "arktype";
import { metabench } from "./metabench.js";

// Simulated pre-instantiated $ZodError
class $ZodError extends Error {
  issues: unknown[] = [];
}
const INVALID = new $ZodError();

const DATA = Array.from({ length: 1000 }, () =>
  Object.freeze({
    number: 1,
    negNumber: -1,
    maxNumber: Number.MAX_VALUE,
    string: "string",
    longString: "Lorem ipsum dolor sit amet, consectetur adipiscing elit.",
    boolean: true,
    deeplyNested: Object.freeze({
      foo: "bar",
      num: 1,
      bool: false,
    }),
  })
);

// Core _run function - returns T | $ZodError
function _run(input: any) {
  if (typeof input !== "object" || input === null) return INVALID;
  if (typeof input.number !== "number") return INVALID;
  if (typeof input.negNumber !== "number") return INVALID;
  if (typeof input.maxNumber !== "number") return INVALID;
  if (typeof input.string !== "string") return INVALID;
  if (typeof input.longString !== "string") return INVALID;
  if (typeof input.boolean !== "boolean") return INVALID;
  const dn = input.deeplyNested;
  if (typeof dn !== "object" || dn === null) return INVALID;
  if (typeof dn.foo !== "string") return INVALID;
  if (typeof dn.num !== "number") return INVALID;
  if (typeof dn.bool !== "boolean") return INVALID;
  return {
    number: input.number,
    negNumber: input.negNumber,
    maxNumber: input.maxNumber,
    string: input.string,
    longString: input.longString,
    boolean: input.boolean,
    deeplyNested: { foo: dn.foo, num: dn.num, bool: dn.bool },
  };
}

// safeParse() - wraps result
function safeParse(input: any) {
  const result = _run(input);
  if (result === INVALID) return { success: false as const, error: INVALID };
  return { success: true as const, data: result };
}

// ArkType schema for comparison
const arkSchema = type({
  number: "number",
  negNumber: "number",
  maxNumber: "number",
  string: "string",
  longString: "string",
  boolean: "boolean",
  deeplyNested: {
    foo: "string",
    num: "number",
    bool: "boolean",
  },
});

export let sink: any;

metabench("valid: check method comparison", {
  "=== INVALID"() {
    for (const item of DATA) {
      const r = _run(item);
      if (r === INVALID) sink = null;
      else sink = r;
    }
  },
  "instanceof $ZodError"() {
    for (const item of DATA) {
      const r = _run(item);
      if (r instanceof $ZodError) sink = null;
      else sink = r;
    }
  },
  safeParse() {
    for (const item of DATA) {
      const r = safeParse(item);
      if (!r.success) sink = null;
      else sink = r.data;
    }
  },
  "arktype (instanceof)"() {
    for (const item of DATA) {
      const r = arkSchema(item);
      if (r instanceof type.errors) sink = null;
      else sink = r;
    }
  },
}).run();

// Invalid data - wrong type on first check
const INVALID_DATA = Array.from({ length: 1000 }, () =>
  Object.freeze({
    number: "not a number", // wrong type - fails fast
    negNumber: -1,
    maxNumber: Number.MAX_VALUE,
    string: "string",
    longString: "Lorem ipsum dolor sit amet.",
    boolean: true,
    deeplyNested: Object.freeze({ foo: "bar", num: 1, bool: false }),
  })
);

metabench("invalid: check method comparison", {
  "=== INVALID"() {
    for (const item of INVALID_DATA) {
      const r = _run(item);
      if (r === INVALID) sink = null;
      else sink = r;
    }
  },
  "instanceof $ZodError"() {
    for (const item of INVALID_DATA) {
      const r = _run(item);
      if (r instanceof $ZodError) sink = null;
      else sink = r;
    }
  },
  safeParse() {
    for (const item of INVALID_DATA) {
      const r = safeParse(item);
      if (!r.success) sink = null;
      else sink = r.data;
    }
  },
  "arktype (instanceof)"() {
    for (const item of INVALID_DATA) {
      const r = arkSchema(item);
      if (r instanceof type.errors) sink = null;
      else sink = r;
    }
  },
}).run();
